function card(label,value,sub=''){return `<div class="card"><div class="label">${escapeHtml(label)}</div><div class="value">${escapeHtml(value)}</div>${sub?`<div class="sub">${escapeHtml(sub)}</div>`:''}</div>`}
function groupedTableHTML(rows,cols,groupBy,selectId='task_id'){if(!groupBy)return tableHTML(rows,cols,{selectId});if(!rows.length)return '<div class="empty">No records found.</div>';let last=Symbol('start'),body='';for(const r of rows){const g=String(r[groupBy]??'Unassigned');if(g!==last){body+=`<tr class="group-row"><td colspan="${cols.length}"><b>${escapeHtml(groupBy)}: ${escapeHtml(g||'Unassigned')}</b></td></tr>`;last=g}body+=`<tr data-id="${escapeHtml(r[selectId]||'')}">${cols.map(c=>`<td class="${c.num?'num':''}">${c.render?c.render(r):escapeHtml(r[c.key]??'—')}</td>`).join('')}</tr>`}return `<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${escapeHtml(c.label)}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
function filterTasks(){let rows=taskRows(state.model,state.projId);if(state.search){const q=state.search.toLowerCase();rows=rows.filter(t=>[t.task_code,t.task_name,t.status_code,t.task_type,t.wbs_id].some(v=>String(v||'').toLowerCase().includes(q)))}rows=applyFilterGroup(rows,state.filterGroup);const layout=state.layouts.find(x=>x.id===state.activeLayoutId)||defaultLayout();return applyLayoutSort(rows,layout)}

async function loadFile(file,isCompare=false){try{const text=await file.text();const m=parseScheduleText(text,file.name);if(isCompare){state.compareModel=m;state.compareProjId=m.table('PROJECT')[0]?.proj_id||null;toast(`Comparison schedule loaded: ${file.name}`);setView('compare');return}state.model=m;state.sourceFormat=m.sourceFormat||'xer';state.history=new EditHistory(m);state.dirty=false;state.baselines=[];state.primaryBaselineId=null;state.selectedBaselineId=null;state.lastCalc=null;state.fileName=file.name;state.projId=m.table('PROJECT')[0]?.proj_id||m.table('TASK')[0]?.proj_id||null;state.selectedTaskId=m.table('TASK')[0]?.task_id||null;state.selectedWbsId=wbsRows(m,state.projId)[0]?.wbs_id||null;state.selectedFloatTarget=state.selectedTaskId;state.search='';state.revisionSnapshots=[snapshotModel(m,`Loaded ${file.name}`)];state.audit=new AuditLog();state.audit.add('Open schedule',{file:file.name,format:state.sourceFormat});const integrity=validateModelIntegrity(m,{projectId:state.projId});if(integrity.issues.length)console.warn('Schedule integrity findings',integrity);$('#fileStatus').textContent=`${file.name} • ${formatLabel(state.sourceFormat)} • ${m.rowCount().toLocaleString()} canonical rows${integrity.counts.errors?` • ${integrity.counts.errors} integrity error(s)`:''}`;populateProjects();$('#exportBtn').disabled=false;updateEditButtons();crumb();render();toast(`Loaded ${file.name}`)}catch(e){console.error(e);alert(`Could not load schedule:\n${e.message}`)}}
