 set('#sOOS','outOfSequenceMode');set('#sLagCal','relationshipLagCalendar');set('#sExpected','expectedFinishMode');set('#sSuspend','suspendResumeMode');set('#sFloatMode','floatMode');set('#sFinishBy','finishBy');set('#sTFBasis','totalFloatBasis');set('#sExternal','externalRelationshipMode');set('#sExceptionMode','calendarExceptionMode');set('#sShiftBoundary','shiftBoundaryMode');set('#sLevel','resourceLevelingEnabled',Boolean);set('#sPriority','resourcePriorityField');set('#sGran','levelingGranularityHours',Number);set('#sCurves','resourceCurveMode');set('#sStrict','strictValidation',Boolean);set('#sHpd','hoursPerDay',Number);set('#sLong','longDurationDays',Number);set('#sFloat','highFloatDays',Number);set('#sLag','lagDays',Number);
