let autosaveTimer=null;
function scheduleAutosave(){if(!state.autosaveEnabled||!state.model)return;clearTimeout(autosaveTimer);autosaveTimer=setTimeout(()=>saveLocalWorkspace(true).catch(()=>{}),600)}
function projectPackage(){return makeProjectPackage({model:state.model,settings:state.settings,baselines:state.baselines,bimModels:state.bimModels,layouts:state.layouts,audit:state.audit.items,scenarios:state.scenarios})}
function modelFromPackage(pkg){const tables=new Map((pkg.tables||[]).map(([n,t])=>[n,{name:t.name||n,fields:[...(t.fields||[])],rows:(t.rows||[]).map(r=>({...r}))}]));const m=new XERModel({header:pkg.header||[],tables,warnings:[],sourceText:''});m.sourceFormat=pkg.sourceFormat||'xer';return m}
async function saveLocalWorkspace(silent=false){if(!state.model)return;const id=state.workspaceId||`project-${state.projId||'schedule'}`;state.workspaceId=id;await saveWorkspace({id,name:currentProject()?.proj_short_name||currentProject()?.proj_name||state.fileName,updatedAt:new Date().toISOString(),package:projectPackage()});if(!silent)toast('Project workspace saved locally')}
function saveProjectPackage(){if(!state.model)return;downloadText(`${baseName()}.ussproj`,serializeProjectPackage(projectPackage()),'application/json;charset=utf-8');toast('Project package downloaded')}
async function openProjectPackage(file){try{const pkg=parseProjectPackage(await file.text());state.model=modelFromPackage(pkg);state.sourceFormat=state.model.sourceFormat;state.settings={...state.settings,...(pkg.settings||{})};state.baselines=(pkg.baselines||[]).map(b=>{if(b.model)return b;const bm=new XERModel({header:[],tables:new Map((b.tables||[]).map(([n,t])=>[n,{name:t.name||n,fields:[...(t.fields||[])],rows:(t.rows||[]).map(r=>({...r}))}])),warnings:[],sourceText:''});bm.sourceFormat=b.format||'xer';return {...b,model:bm}});state.primaryBaselineId=state.baselines.find(b=>b.role==='Primary')?.id||null;state.selectedBaselineId=state.primaryBaselineId||state.baselines[0]?.id||null;state.bimModels=pkg.bimModels||[];state.layouts=pkg.layouts?.length?pkg.layouts:[defaultLayout()];state.scenarios=pkg.scenarios||[];state.audit=new AuditLog();state.audit.items=pkg.audit||[];state.projId=state.model.table('PROJECT')[0]?.proj_id||state.model.table('TASK')[0]?.proj_id||null;state.history=new EditHistory(state.model);state.fileName=file.name;state.selectedTaskId=state.model.table('TASK')[0]?.task_id||null;state.selectedWbsId=wbsRows(state.model,state.projId)[0]?.wbs_id||null;state.revisionSnapshots=[snapshotModel(state.model,'Package opened')];state.dirty=false;populateProjects();updateEditButtons();render();toast('Project package opened')}catch(e){alert(`Could not open project package: ${e.message}`)}}
function exportCurrent(){if(!state.model)return;let rows=[],name=state.view;switch(state.view){case'activities':rows=filterTasks();break;case'relationships':rows=predRows(state.model,state.projId);break;case'resources':rows=summarizeResources(state.model,state.projId);break;case'resourceSheet':rows=resourceSheetRows(state.model,state.projId);name='resource-sheet';break;case'resourceProfiles':rows=buildResourceTimeSeries(state.model,state.projId,{bucket:state.resourceBucket,resourceId:state.selectedResourceId,mode:state.resourceMode});name='resource-profile';break;case'analysis':rows=analyzeSchedule(state.model,state.projId,state.settings).issues;break;case'baselines':{const b=selectedBaseline();rows=b?baselineRows(state.model,state.projId,b,state.settings.hoursPerDay):[];name='baseline-variance';break}case'compare':rows=state.compareModel?compareModels(state.compareModel,state.model,state.compareProjId,state.projId).changes:[];break;case'raw':rows=state.model.table(state.rawTable||'TASK');name=state.rawTable||'TASK';break;default:rows=taskRows(state.model,state.projId)}if(!rows.length)return toast('Nothing to export in this view');downloadText(`${name}.csv`,toCSV(rows),'text/csv;charset=utf-8');}

